contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint value, uint seed) public payable {
        require(address(this).balance >= seed, "insufficient test balance");

        // Establish some balance in c so a successful withdraw is possible,
        // and give the test contract a known starting balance for comparison.
        c.sendMoney{value: seed}(address(c), bytes(""));

        address ownerBefore = c.owner();
        uint cBalBefore = address(c).balance;
        uint selfBalBefore = address(this).balance;
        uint depositsBefore = c.depositsCount();

        bool reverted;
        try c.withdraw(value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint cBalAfter = address(c).balance;
        uint selfBalAfter = address(this).balance;
        uint depositsAfter = c.depositsCount();

        // General rule: the call succeeds exactly when the caller is the owner
        // and the requested value is not larger than c's balance; on success the
        // owner's balance increases by value and c's balance decreases by value;
        // on failure nothing changes.  (depositsCount must never change here.)
        assert(
            reverted == (ownerBefore != address(this) || value > cBalBefore)
            && depositsAfter == depositsBefore
            && (reverted
                ? (cBalAfter == cBalBefore && selfBalAfter == selfBalBefore)
                : (cBalAfter == cBalBefore - value && selfBalAfter == selfBalBefore + value)
            )
        );
    }

    receive() external payable {}
}

